import {type PropsWithChildren, createContext, use, useMemo, useState} from 'react'

export type TimeSpan = '7 days' | '30 days' | '60 days' | '90 days'
const InsightsTimeSpanMap: Record<TimeSpan, string> = {
  '7 days': 'week',
  '30 days': 'month',
  '60 days': 'month',
  '90 days': 'month',
}
type TimeSpanContextType = {
  timeSpan: TimeSpan
  displayTimeSpan: string
  insightsTimeSpan: string
  setTimeSpan: (timeSpan: TimeSpan) => void
}

export const TimeSpanContext = createContext<TimeSpanContextType | undefined>(undefined)

export function TimeSpanProvider({children}: PropsWithChildren) {
  const [timeSpan, setTimeSpan] = useState<TimeSpan>('7 days')
  const value = useMemo(
    () => ({
      timeSpan,
      displayTimeSpan: `in the last ${timeSpan}`,
      insightsTimeSpan: InsightsTimeSpanMap[timeSpan],
      setTimeSpan,
    }),
    [timeSpan, setTimeSpan],
  )
  return <TimeSpanContext value={value}>{children}</TimeSpanContext>
}

export function useTimeSpan(): TimeSpanContextType {
  const context = use(TimeSpanContext)
  if (!context) {
    throw new Error('useTimeSpan must be used within a TimeSpanProvider')
  }
  return context
}
