import {clsx} from 'clsx'
import {Link} from '@primer/react'
import {ArrowDownIcon, ArrowUpIcon} from '@primer/octicons-react'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {ssrSafeLocation} from '@github-ui/ssr-utils'
import type {
  dashboardRoute,
  orgDashboardRoute,
  stafftoolsDashboardRoute,
  stafftoolsOrgDashboardRoute,
} from '../routes/dashboard-route'
import type {DashboardFilter, Metric} from '../types'
import styles from './MetricCards.module.css'

type DashboardRouteConfig =
  | typeof dashboardRoute
  | typeof orgDashboardRoute
  | typeof stafftoolsDashboardRoute
  | typeof stafftoolsOrgDashboardRoute

export function MetricCards({routeConfig}: {routeConfig: DashboardRouteConfig}) {
  const {
    data: {metrics, filter},
  } = useRouteQuery(routeConfig, 'mainQuery')
  return (
    <div className={styles.MetricCards}>
      {metrics.map(card => (
        <MetricCard key={card.name} {...card} filter={filter} />
      ))}
    </div>
  )
}

function MetricCard({
  name,
  isPercentage,
  value,
  valueDiffPercentage,
  link,
  filter,
}: Metric & {filter: DashboardFilter}) {
  const displayTimeSpan = 'in the time period' // TODO: update this to include the actual time span once the filter bar supports it
  const metricDisplayText = isPercentage ? `${value}%` : value.toString()
  const metricPrecentageDiffDisplayText = valueDiffPercentage ? `${valueDiffPercentage}%` : null
  const colorClass = (valueDiffPercentage ?? 0) >= 0 ? 'fgColor-success' : 'fgColor-danger'
  const DiffIcon = (valueDiffPercentage ?? 0) >= 0 ? ArrowUpIcon : ArrowDownIcon

  if (link) {
    const url = new URL(link.href, ssrSafeLocation.origin)
    if (filter.evaluateStatus) url.searchParams.set('evaluate_status', filter.evaluateStatus)
    if (filter.branch && filter.branch !== 'all') url.searchParams.set('ref', filter.branch)
    if (filter.ruleset) url.searchParams.set('ruleset', filter.ruleset.name)
    if (filter.created) url.searchParams.set('created', filter.created)
    link = {
      ...link,
      href: url.toString(),
    }
  }

  return (
    <div className={clsx(styles.MetricCard, 'Box tmp-p-3 gap-1 flex-1')}>
      <div className={clsx(styles.Title, 'text-bold f4')}>{name}</div>
      {link && (
        <div className={styles.Link}>
          <Link href={link.href}>{link.displayText}</Link>
        </div>
      )}
      <div className={clsx(styles.Content, 'd-flex flex-items-center gap-1')}>
        <div className={clsx(styles.Metric, !metricPrecentageDiffDisplayText && 'pr-1', 'f3')}>{metricDisplayText}</div>
        {metricPrecentageDiffDisplayText && (
          <div className={colorClass}>
            <DiffIcon fill={colorClass} className="pl-0" />
            {metricPrecentageDiffDisplayText}
          </div>
        )}
        {displayTimeSpan && <div className={styles.TimeSpan}>{displayTimeSpan}</div>}
      </div>
    </div>
  )
}
