import {mainQuery} from '@github-ui/react-core/future/main-query'
import {ruleInsightsDashboardAppBuilder} from '../config/app-builder'
import type {SourceType} from '@github-ui/repos-rules/types/rules-types'
import type {BypassesByActor, DashboardFilter, Metric, Series} from '../types'

export type DashboardResponse = {
  sourceType: SourceType
  source?: {ownerLogin: string; name: string}
  branchIsValid?: boolean
  filter: DashboardFilter
  rulesets: Array<{name: string}>
  ruleSuites: Series[]
  bypassesByActor: BypassesByActor[]
  metrics: Metric[]
}

const dashboardQueries = [
  mainQuery<DashboardResponse>({
    queryDeps: ({pathname, searchParams}) => ({
      pathname,
      searchParams: {
        evaluate_status: searchParams.get('evaluate_status'),
        ref: searchParams.get('ref'),
        ruleset: searchParams.get('ruleset'),
        created: searchParams.get('created'),
      },
    }),
  }),
] as const

export const dashboardRoute = ruleInsightsDashboardAppBuilder.createQueryRouteConfig('dashboardRoute', {
  path: '/:owner/:repo/settings/rules/dashboard',
  queries: [...dashboardQueries],
})

export const orgDashboardRoute = ruleInsightsDashboardAppBuilder.createQueryRouteConfig('orgDashboardRoute', {
  path: '/organizations/:org/settings/rules/dashboard',
  queries: [...dashboardQueries],
})

export const stafftoolsDashboardRoute = ruleInsightsDashboardAppBuilder.createQueryRouteConfig(
  'stafftoolsDashboardRoute',
  {
    path: '/stafftools/repositories/:owner/:repo/repository_rules/dashboard',
    queries: [...dashboardQueries],
  },
)

export const stafftoolsOrgDashboardRoute = ruleInsightsDashboardAppBuilder.createQueryRouteConfig(
  'stafftoolsOrgDashboardRoute',
  {
    path: '/stafftools/users/:organizationId/organization_rules/dashboard',
    queries: [...dashboardQueries],
  },
)
